        pq.add(10);
        pq.add(20);
        pq.add(3);
       
        pq.add(5);
        pq.add(40);


        System.out.println(pq.peek()); // max priority element

       // pq.remove(); // removes max priority element

        System.out.println(pq.peek()); // max priority element


System.out.println(pq.size()); //                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               